const paths={home:'M3 10 12 3l9 7v10H3Z M9 20v-7h6v7',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',chart:'M3 3v18h18 M7 15v-4 M12 15V6 M17 15V9',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h.01 M3 12h.01 M3 18h.01',target:'M21 12a9 9 0 1 1-9-9 M17 12a5 5 0 1 1-5-5 M12 12l9-9 M17 3h4v4',wallet:'M3 7V5a2 2 0 0 1 2-2h13v4 M3 7h18v14H3Z M16 12h5v5h-5z',plus:'M12 5v14 M5 12h14',arrowUp:'m6 15 9-9 M6 6h9v9',arrowDown:'m6 6 9 9 M6 15h9V6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',close:'m6 6 12 12 M6 18 18 6',shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7Z m-5 9 3 3 6-6',lock:'M5 10h14v11H5Z M8 10V6a4 4 0 0 1 8 0v4 M12 14v3',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',basket:'m7 9 5-6 5 6 M3 9h18l-3 11H6Z M9 12v5 M15 12v5',cup:'M4 4h12v10a6 6 0 0 1-12 0Z M16 5h2a3 3 0 0 1 0 6h-2 M3 21h15',car:'m5 10 2-6h10l2 6 M3 10h18v9H3Z M5 19v2 M19 19v2 M6 14h2 M16 14h2',bag:'M4 7h16l1 14H3Z M8 8V6a4 4 0 0 1 8 0v2',heart:'M12 21 3 12C-3 4 8-1 12 7c4-8 15-3 9 5Z',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',book:'M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1Z M12 5v15',repeat:'m17 2 4 4-4 4 M3 11V6h18 M7 22l-4-4 4-4 M21 13v5H3',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3c5 5 5 13 0 18-5-5-5-13 0-18',briefcase:'M3 7h18v14H3Z M8 7V3h8v4 M3 12c6 3 12 3 18 0 M12 12v4',gift:'M3 8h18v4H3Z M5 12v9h14v-9 M12 8v13 M12 8C0 8 8-5 12 8c4-13 12 0 0 0',search:'M16 16l5 5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',download:'M12 3v12 m-5-5 5 5 5-5 M3 16v5h18v-5',upload:'M12 16V4 m-5 5 5-5 5 5 M3 16v5h18v-5',trash:'M3 6h18 M8 6V3h8v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',edit:'m15 3 6 6-12 12H3v-6Z M12 6l6 6',check:'m4 12 5 5L20 6',info:'M12 10v7 M12 6h.01 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',calendar:'M3 5h18v16H3Z M7 3v4 M17 3v4 M3 10h18'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const navs=[['overview','home','Обзор'],['history','list','Операции'],['analytics','chart','Аналитика'],['plans','target','Планы'],['wallets','wallet','Счета']];
const cloud=new CloudStore();let state=freshState(),loadFailure=false;try{state=cloud.load();}catch{loadFailure=true;}
let demo=false,realState=state,page='overview',period='month',historyType='all',historyCategory='all',query='',editing=null,selectedCategory='food',txType='expense',modalOpener=null,toastTimer,refreshing=false;
const motion=ambient($('#ambient')); const displayNames=new Intl.DisplayNames(['ru'],{type:'currency'});
const codes=[...new Set(['UZS','USD','EUR','RUB','KZT','GBP','AED','CNY',...(Intl.supportedValuesOf?Intl.supportedValuesOf('currency'):['JPY','TRY','CHF','KRW','INR','UAH']),...Object.keys(state.rates)])];
const money=(n,c=state.currency,compact=false)=>n===null?'Нет курса':new Intl.NumberFormat('ru-RU',{maximumFractionDigits:compact?0:2,notation:compact&&Math.abs(n)>=1e7?'compact':'standard'}).format(n)+(c==='UZS'?' сум':` ${c}`);
const number=(n)=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(n);
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('ru',{day:'numeric',month:'short'});
const cBy=id=>categories.find(c=>c.id===id)||categories[10];
const filtered=()=>state.transactions.filter(t=>inPeriod(t,period));
const sorted=tx=>[...tx].sort((a,b)=>b.date.localeCompare(a.date));
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function commit(fn){try{if(loadFailure)throw Error('Хранилище не прочитано. Сначала восстановите резервную копию.');const next=structuredClone(state);fn(next);validateState(next);if(!demo)cloud.persist(next);state=next;if(!demo)realState=state;return true;}catch(e){toast(e.message);return false;}}
function actButton(action,text,ico='plus',cls='primary',extra=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${icon(ico)}${text}</button>`;}
function segments(){return `<div class="segmented" aria-label="Период">${[['week','7 дней'],['month','Месяц'],['year','Год'],['all','Всё время']].map(([id,name])=>`<button class="${period===id?'selected':''}" data-action="period" data-id="${id}" aria-pressed="${period===id}">${name}</button>`).join('')}</div>`;}
function empty(title,text,action='add-expense',label='Добавить расход',ico='chart'){return `<div class="empty">${icon(ico)}<h3>${title}</h3><p>${text}</p>${action?actButton(action,label,'plus','small'):''}</div>`;}
function balanceTotal(){let value=0,missing=0;for(const a of state.accounts){const n=convert(fromMinor(accountBalance(a,state.transactions),a.currency),a.currency,state.currency,state.rates);if(n===null)missing++;else value+=n;}return{value,missing};}
function metrics(s,mode=false){const count=filtered().filter(t=>t.type==='expense').length;return `<div class="${mode?'stats-grid':'metric-grid'}">${[
 ['Доходы',money(s.income,state.currency,true),'arrowDown','positive','За выбранный период'],['Расходы',money(s.expense,state.currency,true),'arrowUp','negative',`${count} ${count===1?'операция':'операций'}`],['Разница',money(s.net,state.currency,true),'chart',s.net>=0?'positive':'negative','Доходы минус расходы'],['Сбережения',s.savingRate===null?'—':number(s.savingRate)+'%','target','','Доля дохода после расходов']
 ].map(([name,value,ico,cl,sub],i)=>`<div class="card metric"><div class="metric-top">${name}<span class="metric-icon ${i===1?'out':i>1?'purple':''}">${icon(ico)}</span></div><strong class="${cl}">${value}</strong><small>${sub}</small></div>`).join('')}</div>`;}
function transactionRows(tx){return tx.map(t=>{const c=cBy(t.category);return `<button class="transaction" data-action="detail" data-id="${esc(t.id)}"><span class="category-icon" style="--c:${c.color}">${icon(c.icon)}</span><span class="transaction-main"><strong>${esc(t.note)}</strong><small>${c.name} · ${dateLabel(t.date)}</small></span><span class="transaction-amount"><strong class="${t.type==='income'?'positive':''}">${t.type==='income'?'+':'−'}${money(fromMinor(t.amount,t.currency),t.currency)}</strong><small>${esc(state.accounts.find(a=>a.id===t.account)?.bank||'')}</small></span></button>`;}).join('');}
function donut(s){const all=Object.entries(s.groups).sort((a,b)=>b[1]-a[1]);let offset=0;const circles=all.map(([id,val])=>{const frac=val/s.expense,part=frac*326.73;const out=`<circle cx="70" cy="70" r="52" fill="none" stroke="${cBy(id).color}" stroke-width="14" stroke-dasharray="${Math.max(0,part-3)} ${326.73-Math.max(0,part-3)}" stroke-dashoffset="${-offset}" stroke-linecap="round"/>`;offset+=part;return out;}).join('');return `<div class="donut-layout"><div class="donut" role="img" aria-label="Расходы по категориям"><svg viewBox="0 0 140 140"><circle cx="70" cy="70" r="52" fill="none" stroke="#292131" stroke-width="14"/>${circles}</svg><div class="donut-center"><span>КАТЕГОРИЙ</span><strong>${all.length}</strong><span>в ваших расходах</span></div></div><div class="legend-list">${all.slice(0,5).map(([id,val])=>`<div class="legend-row"><span><i class="dot" style="--c:${cBy(id).color}"></i>${cBy(id).name.split(' и ')[0]}</span><b>${number(val/s.expense*100)}%</b></div>`).join('')}${all.length>5?`<small>+ ещё ${all.length-5} категорий</small>`:''}${!all.length?'<small>Здесь появится структура ваших расходов.</small>':''}</div></div>`;}
function series(){const tx=filtered(),now=new Date();let labels=[],keys=[];if(period==='year'||period==='all'){const y=now.getFullYear();if(period==='all'&&tx.length){const min=tx.reduce((a,t)=>a<t.date?a:t.date, today());let d=new Date(min.slice(0,7)+'-01T12:00:00');while(d<=now&&keys.length<1200){keys.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`);labels.push(d.toLocaleDateString('ru',{month:'short',year:'2-digit'}));d.setMonth(d.getMonth()+1);}}else{for(let i=0;i<12;i++){keys.push(`${y}-${String(i+1).padStart(2,'0')}`);labels.push(new Date(y,i,1).toLocaleDateString('ru',{month:'short'}));}}}else{let days=period==='week'?7:new Date(now.getFullYear(),now.getMonth()+1,0).getDate();for(let i=0;i<days;i++){const d=period==='week'?new Date(now.getFullYear(),now.getMonth(),now.getDate()-6+i):new Date(now.getFullYear(),now.getMonth(),i+1);keys.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`);labels.push(String(d.getDate()));}}const income=keys.map(()=>0),expense=keys.map(()=>0);for(const t of tx){const index=keys.indexOf(t.date.slice(0,keys[0]?.length||10));const value=transactionValue(t,state.currency,state.rates);if(index>=0&&value!==null)(t.type==='income'?income:expense)[index]+=value;}return{labels,income,expense};}
function bars(){const {labels,income,expense}=series(),max=Math.max(...income,...expense,1),w=540,h=180,left=44,bottom=155,area=480,step=area/Math.max(labels.length,1);let svg='';for(let i=0;i<4;i++){const y=12+i*45;svg+=`<line class="grid" x1="${left}" y1="${y}" x2="530" y2="${y}"/><text x="0" y="${y+4}">${new Intl.NumberFormat('ru',{notation:'compact',maximumFractionDigits:0}).format(max*(1-i/3))}</text>`;}labels.forEach((label,i)=>{const x=left+i*step;for(const[v,j,color]of[[income[i],0,'#285b50'],[expense[i],1,'#604181']]){const bh=v/max*135;svg+=`<rect class="bar" x="${x+step*.1+j*step*.4}" y="${bottom-bh}" width="${Math.max(1,step*.29)}" height="${bh}" rx="2" fill="${color}"><title>${label}: ${money(v)}</title></rect>`;}if(i%Math.ceil(labels.length/7)===0)svg+=`<text x="${x+step*.5}" y="177" text-anchor="middle">${esc(label)}</text>`;});return `<svg class="chart-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="График доходов и расходов: зелёные столбцы — доходы, фиолетовые — расходы">${svg}</svg>`;}
function trend(){const {labels,income,expense}=series();let total=0;const values=income.map((n,i)=>(total+=n-expense[i]));const lo=Math.min(0,...values),hi=Math.max(1,...values),span=hi-lo;const pts=values.map((v,i)=>`${45+i*475/Math.max(1,values.length-1)},${145-(v-lo)/span*125}`);return `<svg class="chart-svg" viewBox="0 0 540 180" role="img" aria-label="Накопленная разница доходов и расходов"><defs><linearGradient id="fillTrend" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#543375" stop-opacity=".5"/><stop offset="1" stop-color="#543375" stop-opacity="0"/></linearGradient></defs>${[20,82,145].map(y=>`<line class="grid" x1="45" y1="${y}" x2="525" y2="${y}"/>`).join('')}<path d="M${pts.join(' L')} L520,150 L45,150 Z" fill="url(#fillTrend)"/><path class="line" d="M${pts.join(' L')}" stroke="#8a67a6" stroke-width="2.4" fill="none"/><text x="45" y="175">${esc(labels[0]||'')}</text><text x="520" y="175" text-anchor="end">${esc(labels.at(-1)||'')}</text><text x="45" y="13">${money(hi,state.currency,true)}</text></svg>`;}
function budgetRows(limit=100){return state.budgets.slice(0,limit).map(b=>{const s=stats(state.transactions.filter(t=>t.type==='expense'&&t.category===b.category&&inPeriod(t,'month')),b.currency,state.rates);const max=fromMinor(b.limit,b.currency),pct=s.expense/max*100;return `<div class="budget-item"><div class="budget-label"><span>${cBy(b.category).name}</span><button class="link-btn" data-action="budget-edit" data-id="${b.id}" aria-label="Изменить бюджет ${cBy(b.category).name}">${number(pct)}% ${icon('chevron')}</button></div><div class="track ${pct>100?'over':''}" style="--progress:${Math.min(pct,100)}%"><i></i></div><div class="budget-foot"><span>${money(s.expense,b.currency,true)}</span><span>из ${money(max,b.currency,true)}</span></div>${s.missing?'<small class="danger-text">Часть расходов без курса</small>':''}</div>`;}).join('');}
function overview(){const s=stats(filtered(),state.currency,state.rates),total=balanceTotal();const top=Object.entries(s.groups).sort((a,b)=>b[1]-a[1])[0];return `<div class="heading"><div><div class="caption">Ваш личный финансовый ритм</div><h1>Деньги под контролем.</h1><p>Чуть больше ясности. Чуть ближе к вашим целям.</p></div>${actButton('add-expense','Новая операция')}</div>
 <div class="overview-grid"><section class="card hero"><div><div class="hero-top"><span class="eyebrow">Общий баланс счетов</span><button class="icon-btn" data-action="hide" aria-label="${state.hidden?'Показать':'Скрыть'} баланс">${icon('eye')}</button></div><div class="balance">${state.hidden?'••• •••':number(total.value)}<small>${state.currency==='UZS'?'сум':state.currency}</small></div><span class="tag">${icon('wallet')} ${state.accounts.length} ${state.accounts.length===1?'счёт':'счета'} · ручной учёт</span>${total.missing?'<div class="notice">Не все счета включены: обновите курсы.</div>':''}</div><div class="hero-bottom">${actButton('add-expense','Расход','arrowUp')}${actButton('add-income','Доход','arrowDown','ghost')}</div></section>${metrics(s)}</div>
 ${!state.transactions.length?`<section class="card onboard section-space"><div class="caption">Начнём с малого</div><h2>Первый шаг к спокойствию — одна запись.</h2><p>Добавьте доход или расход. ASDTrecker соберёт статистику, покажет привычки и поможет следить за планами.</p><div class="hero-bottom">${actButton('add-expense','Моя первая запись')}${actButton('demo','Посмотреть пример','spark','ghost')}</div></section>`:''}
 <div class="toolbar section-space">${segments()}</div>${s.missing?missingNotice(s.missing):''}
 <div class="chart-grid"><section class="card"><div class="card-head"><h2>Движение денег</h2><div class="chart-legend"><span><i class="dot" style="--c:#285b50"></i>Доходы</span><span><i class="dot" style="--c:#604181"></i>Расходы</span></div></div>${bars()}<div class="chart-bottom"><span>Разница за период</span><b>${money(s.net)}</b></div></section><section class="card"><div class="card-head"><h2>Куда уходят деньги</h2>${icon('chart')}</div>${donut(s)}<div class="chart-bottom"><span>Всего потрачено</span><b>${money(s.expense)}</b></div></section></div>
 <div class="row-grid section-space"><section class="card"><div class="card-head"><h2>Последние операции</h2><button class="link-btn" data-action="nav" data-id="history">Все ${icon('chevron')}</button></div>${state.transactions.length?transactionRows(sorted(state.transactions).slice(0,5)):empty('История начинается здесь','Каждой трате — категория и понятное название.','','')}</section><section class="card"><div class="card-head"><h2>Бюджет месяца</h2><button class="link-btn" data-action="budget-add" aria-label="Добавить бюджет">${icon('plus')}</button></div>${state.budgets.length?budgetRows(3):empty('Тратьте осознанно','Установите лимит для важной категории.','budget-add','Создать бюджет','target')}<div class="insight">${icon('spark')}<div><strong>${top?cBy(top[0]).name+' — '+number(top[1]/s.expense*100)+'% расходов':'Ваши привычки — в деталях'}</strong>${top?'Самая большая категория за выбранный период. Посмотрите её операции в истории.':'Добавляйте записи, чтобы увидеть, что влияет на ваш бюджет.'}</div></div></section></div>`;}
const missingNotice=n=>`<div class="notice">${n} операций не включены в пересчёт: для них не был указан курс. Их исходные суммы сохранены; добавьте курс через редактирование операции.</div>`;
function history(){const tx=sorted(filtered()).filter(t=>(historyType==='all'||t.type===historyType)&&(historyCategory==='all'||t.category===historyCategory)&&`${t.note} ${cBy(t.category).name} ${t.currency}`.toLowerCase().includes(query.toLowerCase()));let day='';return `<div class="heading"><div><div class="caption">Каждая запись имеет значение</div><h1>Ваши операции</h1><p>История доходов, расходов и повседневных решений.</p></div>${actButton('add-expense','Добавить')}</div><div class="toolbar">${segments()}<div class="search">${icon('search')}<input id="history-search" aria-label="Поиск операций" placeholder="Найти покупку, категорию…" value="${esc(query)}"></div><select id="history-type" aria-label="Тип операции">${[['all','Все операции'],['expense','Расходы'],['income','Доходы']].map(([v,n])=>`<option value="${v}" ${historyType===v?'selected':''}>${n}</option>`).join('')}</select><select id="history-category" aria-label="Категория операций"><option value="all">Все категории</option>${categories.map(c=>`<option value="${c.id}" ${historyCategory===c.id?'selected':''}>${c.name}</option>`).join('')}</select></div><section class="card"><div class="card-head"><h2>Лента операций</h2><small>${tx.length} записей</small></div>${tx.length?tx.map(t=>{let h='';if(day!==t.date){day=t.date;h=`<div class="history-day">${dateLabel(day)} · ${day.slice(0,4)}</div>`;}return h+transactionRows([t]);}).join(''):empty('Пока ничего не найдено','Добавьте запись или измените фильтры.','add-expense','Добавить запись','search')}</section>`;}
function analytics(){const tx=filtered(),s=stats(tx,state.currency,state.rates),expenses=tx.filter(t=>t.type==='expense'),converted=expenses.map(t=>transactionValue(t,state.currency,state.rates)).filter(n=>n!==null),max=Math.max(0,...converted),avg=converted.length?s.expense/converted.length:0;const weekdays=[0,0,0,0,0,0,0];for(const t of expenses){const v=transactionValue(t,state.currency,state.rates);if(v!==null)weekdays[(new Date(t.date+'T12:00:00').getDay()+6)%7]+=v;}const weekdayMax=Math.max(1,...weekdays),names=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'];const now=new Date(),days=new Date(now.getFullYear(),now.getMonth()+1,0).getDate(),heat=Array.from({length:days},(_,i)=>{const d=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return stats(state.transactions.filter(t=>t.date===d),state.currency,state.rates).expense;}),heatMax=Math.max(1,...heat);return `<div class="heading"><div><div class="caption">Увидеть больше</div><h1>Финансы в деталях</h1><p>Ваши привычки, категории и движение к целям.</p></div></div><div class="toolbar">${segments()}</div>${metrics(s,true)}${s.missing?missingNotice(s.missing):''}<div class="analysis-grid section-space"><section class="card"><div class="card-head"><h2>Структура расходов</h2><small>${expenses.length} операций</small></div>${donut(s)}<div class="section-divider"></div>${Object.entries(s.groups).sort((a,b)=>b[1]-a[1]).map(([id,v])=>`<button class="transaction" data-action="category-history" data-id="${id}"><span class="category-icon" style="--c:${cBy(id).color}">${icon(cBy(id).icon)}</span><span class="transaction-main"><strong>${cBy(id).name}</strong><small>${number(v/Math.max(1,s.expense)*100)}% от расходов</small></span><span class="transaction-amount">${money(v,state.currency,true)}</span></button>`).join('')}</section><div><section class="card"><div class="card-head"><h2>Накопленный результат</h2>${icon('chart')}</div>${trend()}<small>Сумма доходов минус расходы с начала периода. Начальные балансы не включены.</small></section><section class="card section-space"><div class="card-head"><h2>Средний и крупный чек</h2>${icon('bag')}</div><div class="budget-label"><span>Средний расход</span><b>${money(avg)}</b></div><div class="section-divider"></div><div class="budget-label"><span>Самая крупная трата</span><b>${money(max)}</b></div></section></div><section class="card"><div class="card-head"><h2>Ритм недели</h2><small>Расходы по дням</small></div>${weekdays.map((v,i)=>`<div class="budget-item"><div class="budget-label"><span>${names[i]}</span><small>${money(v,state.currency,true)}</small></div><div class="track" style="--progress:${v/weekdayMax*100}%"><i></i></div></div>`).join('')}</section><section class="card"><div class="card-head"><h2>Календарь расходов</h2><small>Текущий месяц</small></div><div class="heatmap">${names.map(n=>`<span class="heat-label">${n}</span>`).join('')}${'<span></span>'.repeat((new Date(now.getFullYear(),now.getMonth(),1).getDay()+6)%7)}${heat.map((v,i)=>`<div class="heat-cell" style="background:rgba(95,56,132,${.13+v/heatMax*.65})" title="${i+1}: ${money(v)}">${i+1}</div>`).join('')}</div><div class="insight">${icon('calendar')}<div><strong>${heat.filter(v=>v>0).length} дней с записями расходов</strong>Чем насыщеннее ячейка, тем больше потрачено. Пустая ячейка означает отсутствие записанных расходов.</div></div></section></div>`;}
function plans(){return `<div class="heading"><div><div class="caption">Маленькие шаги. Большие планы.</div><h1>Будущее начинается сейчас</h1><p>Держите расходы в рамках, а мечты — в фокусе.</p></div>${actButton('goal-add','Новая цель')}</div><div class="goals-grid">${state.goals.length?state.goals.map(g=>{const pct=g.saved/g.target*100;return `<section class="card"><div class="card-head"><span class="category-icon">${icon('target')}</span><span class="tag">${pct>=100?'Цель достигнута':number(pct)+'% пути'}</span></div><h2>${esc(g.name)}</h2><div class="goal-amount">${money(fromMinor(g.saved,g.currency),g.currency,true)}</div><small>из ${money(fromMinor(g.target,g.currency),g.currency)}</small><div class="track" style="--progress:${Math.min(100,pct)}%"><i></i></div><div class="hero-bottom">${actButton('goal-save','Записать накопления','plus','small primary',`data-id="${g.id}"`)}${actButton('goal-edit','Изменить','edit','small ghost',`data-id="${g.id}"`)}</div><small class="section-space" style="display:block">Учёт цели отдельно от счетов. Деньги не перемещаются.</small></section>`;}).join(''):`<section class="card full-span">${empty('У каждой мечты есть первый шаг','Путешествие, новая техника или финансовая подушка — задайте свою цель.','goal-add','Создать цель','target')}</section>`}</div><section class="card section-space"><div class="card-head"><h2>Бюджеты на месяц</h2>${actButton('budget-add','Добавить','plus','small')}</div>${state.budgets.length?budgetRows():empty('Лимиты, которые помогают','Выберите категории и комфортную сумму на месяц.','budget-add','Добавить бюджет','chart')}</section>`;}
function wallets(){return `<div class="heading"><div><div class="caption">Вся картина в одном месте</div><h1>Ваши счета</h1><p>Личный учёт балансов. Без переводов и доступа к деньгам.</p></div>${actButton('account-add','Добавить счёт')}</div><div class="wallet-grid">${state.accounts.map(a=>`<section class="card bank-card"><div class="card-head"><div><h2>${esc(a.bank)}</h2><small>${esc(a.name)}</small></div>${icon('wallet')}</div><div><span class="caption">Учётный баланс</span><div class="balance">${state.hidden?'••• •••':money(fromMinor(accountBalance(a,state.transactions),a.currency),a.currency,true)}</div></div><div class="wallet-footer"><span>Внесён вручную · не синхронизирован</span><button class="link-btn" data-action="account-edit" data-id="${esc(a.id)}">Настроить ${icon('chevron')}</button></div></section>`).join('')}</div><section class="card section-space"><div class="card-head"><h2>Связь с банками Узбекистана</h2><span class="tag">Не подключена</span></div><p class="privacy-copy">Agrobank, Uzum Bank и любой другой банк можно добавить как счёт для ручного учёта. Автоматический баланс требует официального доступа банка с правом только на чтение. В этой версии такого подключения нет.</p><div class="security-grid section-space"><div class="security-feature">${icon('shield')}<strong>Никаких переводов</strong><p>Приложение не содержит платёжных методов и не может отправить деньги.</p></div><div class="security-feature">${icon('lock')}<strong>Без реквизитов карты</strong><p>Не нужны номер карты, CVV, банковский пароль или SMS-код.</p></div><div class="security-feature">${icon('eye')}<strong>Прозрачный баланс</strong><p>Начальный остаток плюс доходы минус расходы, которые вы внесли.</p></div></div></section>`;}
function render(){motion(state.motion,navs.findIndex(n=>n[0]===page));$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><img src="logo.svg" alt="Логотип ASDTrecker"><span>ASD<em>Trecker</em><small>личные финансы</small></span></div><div class="caption">Ваше пространство</div><nav>${navs.map(([id,ico,name])=>`<button class="nav-item ${page===id?'active':''}" data-action="nav" data-id="${id}">${icon(ico)}${name}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="nav-item" data-action="settings">${icon('settings')}Настройки</button><div class="security-mini">${icon('shield')}<span>${native?'Локальная защита AES-256-GCM<br>Аккаунт и синхронизация':'Личное пространство<br>Аккаунт и облачная копия'}</span></div><div class="version"><span>ASDTrecker</span><span>v1.1</span></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs">Личное пространство ${icon('chevron')} <b>${navs.find(n=>n[0]===page)[2]}</b></div><div class="brand mobile-brand"><img src="logo.svg" alt=""><span>ASD<em>Trecker</em><small>личные финансы</small></span></div><div class="top-actions"><button class="pill" data-action="currency">${state.currency} ${icon('down')}</button><button class="icon-btn lock-top" data-action="lock" aria-label="Заблокировать">${icon('lock')}</button><button class="icon-btn" data-action="settings" aria-label="Настройки">${icon('settings')}</button></div></header>${demo?`<div class="demo-banner"><span>Демо · вымышленные операции и курсы, изменения не сохраняются</span><button class="btn small" data-action="exit-demo">Мои данные</button></div>`:''}${loadFailure?'<div class="notice">Не удалось прочитать хранилище. Новые записи заблокированы, чтобы не затереть данные. Восстановите копию в настройках.</div>':''}<div class="page">${({overview,history,analytics,plans,wallets}[page])()}</div><footer class="source"><span><i class="status-dot ${navigator.onLine?'':'offline'}"></i>${demo?'Демонстрационные курсы':state.ratesAt?'Курсы от '+new Date(state.ratesAt).toLocaleDateString('ru'):'Курсы ещё не загружены'} · ${navigator.onLine?'онлайн':'офлайн'}</span><a href="https://www.exchangerate-api.com" target="_blank" rel="noopener noreferrer">Курсы: ExchangeRate-API</a></footer></main><nav class="bottom-nav" aria-label="Разделы">${navs.map(([id,ico,name])=>`<button class="${page===id?'active':''}" data-action="nav" data-id="${id}" ${page===id?'aria-current="page"':''}>${icon(ico)}${name}</button>`).join('')}</nav>`;}
function modal(title,body){modalOpener=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Закрыть">${icon('close')}</button></div>${body}</section></div>`;document.body.classList.add('no-scroll');setTimeout(()=>$('.modal input:not([type=checkbox]),.modal button')?.focus(),50);}
function closeModal(){if(!$('#modal-root').firstChild)return false;$('#modal-root').innerHTML='';document.body.classList.remove('no-scroll');modalOpener?.focus?.();return true;}
const currencyOptions=(selected=state.currency)=>codes.map(c=>`<option value="${c}" ${c===selected?'selected':''}>${c} · ${esc(displayNames.of(c))}</option>`).join('');
function categoryButtons(){return categories.filter(c=>!!c.income===(txType==='income')).map(c=>`<button type="button" class="category-btn ${selectedCategory===c.id?'selected':''}" data-action="select-category" data-id="${c.id}" aria-pressed="${selectedCategory===c.id}">${icon(c.icon)}${c.name}</button>`).join('');}
function transactionModal(type='expense',id=null){editing=id;const t=state.transactions.find(t=>t.id===id);txType=t?.type||type;selectedCategory=t?.category||(txType==='income'?'salary':'food');modal(id?'Изменить запись':txType==='expense'?'На что вы потратили?':'Откуда пришёл доход?',`<form id="transaction-form"><div class="field"><label for="amount">Сумма ${txType==='expense'?'расхода':'дохода'}</label><input id="amount" class="amount-input" name="amount" inputmode="decimal" autocomplete="off" placeholder="0" required value="${t?fromMinor(t.amount,t.currency):''}"></div><div class="form-grid"><div class="field"><label for="tx-currency">Валюта операции</label><select id="tx-currency" name="currency">${currencyOptions(t?.currency)}</select></div><div class="field"><label for="tx-date">Дата</label><input id="tx-date" name="date" type="date" required max="${today()}" value="${t?.date||today()}"></div></div><div class="field"><label>Категория · обязательно</label><div class="form-category" id="category-buttons">${categoryButtons()}</div></div><div class="field"><label for="tx-note">${txType==='expense'?'На что именно?':'Источник дохода'} · обязательно</label><input id="tx-note" name="note" required maxlength="160" placeholder="${txType==='expense'?'Например, продукты на неделю':'Например, зарплата за ноябрь'}" value="${esc(t?.note||'')}"></div><div class="field"><label for="tx-account">Счёт для учёта</label><select id="tx-account" name="account">${state.accounts.map(a=>`<option value="${esc(a.id)}" ${a.id===t?.account?'selected':''}>${esc(a.bank)} · ${esc(a.name)} (${a.currency})</option>`).join('')}</select><span class="help">Баланс меняется только в вашем трекере. Это не банковская операция.</span></div><details><summary class="muted">Курс операции / ручной курс</summary><div class="field section-space"><label for="tx-rate">1 USD = сколько единиц валюты операции?</label><input id="tx-rate" name="rate" inputmode="decimal" placeholder="Автоматически по последнему курсу" value="${t?.usdValue?fromMinor(t.amount,t.currency)/t.usdValue:''}"><span class="help">Для старых операций можно указать исторический курс. Для USD всегда 1. Без курса разрешён учёт в валюте счёта; сводка в других валютах будет неполной.</span></div></details><div class="form-error" role="alert"></div><div class="modal-actions"><button class="btn primary wide" type="submit">${icon('check')}Сохранить ${txType==='expense'?'расход':'доход'}</button></div></form>`);}
function detail(id){const t=state.transactions.find(t=>t.id===id);if(!t)return;modal('Детали операции',`<div class="detail-amount ${t.type==='income'?'positive':''}">${t.type==='income'?'+':'−'}${money(fromMinor(t.amount,t.currency),t.currency)}</div>${[['Назначение',t.note],['Категория',cBy(t.category).name],['Дата',dateLabel(t.date)+' '+t.date.slice(0,4)],['Счёт',state.accounts.find(a=>a.id===t.account)?.name],['Курс на дату записи',t.usdValue?`1 USD = ${number(fromMinor(t.amount,t.currency)/t.usdValue)} ${t.currency}`:'Без пересчёта']].map(([k,v])=>`<div class="detail-row"><span>${k}</span><b>${esc(v)}</b></div>`).join('')}<div class="modal-actions">${actButton('transaction-edit','Изменить','edit','primary',`data-id="${id}"`)}${actButton('transaction-delete','Удалить','trash','ghost',`data-id="${id}"`)}</div>`);}
function budgetModal(id=null){const b=state.budgets.find(x=>x.id===id);modal(b?'Изменить бюджет':'Бюджет на месяц',`<form id="budget-form" data-id="${id||''}"><div class="field"><label for="budget-category">Категория</label><select name="category" id="budget-category">${categories.filter(c=>!c.income).map(c=>`<option value="${c.id}" ${b?.category===c.id?'selected':''}>${c.name}</option>`).join('')}</select></div><div class="field"><label for="budget-limit">Лимит на месяц</label><input id="budget-limit" name="limit" inputmode="decimal" required placeholder="1 000 000" value="${b?fromMinor(b.limit,b.currency):''}"></div><div class="field"><label for="budget-currency">Валюта</label><select id="budget-currency" name="currency">${currencyOptions(b?.currency)}</select></div><small>Лимит повторяется каждый календарный месяц.</small><div class="form-error" role="alert"></div><div class="modal-actions">${b?actButton('budget-delete','Удалить','trash','ghost',`type="button" data-id="${b.id}"`):''}<button type="submit" class="btn primary">Сохранить бюджет</button></div></form>`);}
function goalModal(id=null){const g=state.goals.find(x=>x.id===id);modal(g?'Изменить цель':'К чему идём?',`<form id="goal-form" data-id="${id||''}"><div class="field"><label for="goal-name">Название цели</label><input id="goal-name" name="name" required maxlength="60" placeholder="Например, путешествие" value="${esc(g?.name||'')}"></div><div class="form-grid"><div class="field"><label for="goal-target">Нужно накопить</label><input id="goal-target" name="target" required inputmode="decimal" value="${g?fromMinor(g.target,g.currency):''}"></div><div class="field"><label for="goal-saved">Уже накоплено</label><input id="goal-saved" name="saved" required inputmode="decimal" value="${g?fromMinor(g.saved,g.currency):0}"></div></div><div class="field"><label for="goal-currency">Валюта</label><select name="currency" id="goal-currency">${currencyOptions(g?.currency)}</select></div><small>Запись накоплений не списывает деньги со счетов.</small><div class="form-error" role="alert"></div><div class="modal-actions">${g?actButton('goal-delete','Удалить','trash','ghost',`type="button" data-id="${g.id}"`):''}<button type="submit" class="btn primary">Сохранить цель</button></div></form>`);}
function accountModal(id=null){const a=state.accounts.find(x=>x.id===id),used=a&&state.transactions.some(t=>t.account===a.id);modal(a?'Настройка счёта':'Новый счёт',`<form id="account-form" data-id="${id||''}"><div class="field"><label for="account-bank">Банк или тип счёта</label><input id="account-bank" name="bank" list="banks" maxlength="60" required placeholder="Uzum Bank, Agrobank…" value="${esc(a?.bank||'')}"><datalist id="banks">${['Uzum Bank','Agrobank','Наличные','Kapitalbank','Ipak Yuli Bank','Hamkorbank','NBU','Xalq Banki','Asakabank','Ipoteka Bank','TBC Bank','Anorbank'].map(b=>`<option value="${b}">`).join('')}</datalist></div><div class="field"><label for="account-name">Название счёта</label><input id="account-name" name="name" required maxlength="60" placeholder="Основная карта" value="${esc(a?.name||'')}"></div><div class="field"><label for="account-currency">Валюта ${used?'· фиксирована для записанных операций':''}</label><select id="account-currency" name="currency" ${used?'disabled':''}>${currencyOptions(a?.currency)}</select></div><div class="field"><label for="account-opening">Начальный остаток (до всех записанных операций)</label><input id="account-opening" name="opening" required inputmode="decimal" value="${a?fromMinor(a.opening,a.currency):0}"><span class="help">Текущий баланс = начальный остаток + все внесённые доходы − все расходы. Можно указать отрицательный начальный остаток.</span></div><div class="notice">Это ручной учёт. Номер карты и банковские пароли не нужны.</div><div class="form-error" role="alert"></div><div class="modal-actions">${a&&!used&&state.accounts.length>1?actButton('account-delete','Удалить','trash','ghost',`type="button" data-id="${a.id}"`):''}<button type="submit" class="btn primary">Сохранить счёт</button></div></form>`);}
function currencyModal(){modal('Валюта сводки',`<div class="field"><input id="currency-search" placeholder="Поиск: UZS, доллар, евро…" aria-label="Поиск валют"></div><small>Все валюты ISO из списка устройства. Автокурсы — для валют, поддерживаемых провайдером. Остальные можно учитывать с ручным курсом.</small><div class="currency-list section-space" id="currency-list">${currencyRows('')}</div>`);}
function currencyRows(search){return codes.filter(c=>`${c} ${displayNames.of(c)}`.toLowerCase().includes(search.toLowerCase())).map(c=>`<button class="currency-row" data-action="set-currency" data-id="${c}"><strong>${c}</strong><span>${esc(displayNames.of(c))}</span>${state.currency===c?icon('check'):state.rates[c]?'<small>курс есть</small>':'<small>ручной курс</small>'}</button>`).join('');}
function settings(){const secure=native?native.isDeviceSecure():false;modal('Ваше пространство',`<div class="settings-row"><div><strong>Живой 3D-фон</strong><small>Плавное вращение и смена формы при прокрутке</small></div><button class="toggle ${state.motion?'':'off'}" data-action="motion" role="switch" aria-checked="${state.motion}" aria-label="Живой 3D-фон"></button></div><div class="settings-row"><div><strong>Валюта сводки</strong><small>${state.currency} · ${esc(displayNames.of(state.currency))}</small></div><button class="btn small" data-action="currency">Изменить</button></div><div class="settings-row"><div><strong>Курсы валют</strong><small>${state.ratesAt?'Обновлены '+new Date(state.ratesAt).toLocaleString('ru'):'Ещё не загружены'}</small></div><button class="btn small" data-action="refresh" ${refreshing?'disabled':''}>${icon('repeat')}Обновить</button></div><div class="settings-row"><div><strong>${native?'Зашифрованное хранилище':'Локальная копия браузера'}</strong><small>${native?'AES-256-GCM · ключ в Android Keystore':'Здесь данные в localStorage. Для личных финансов используйте APK.'}</small></div>${icon('shield')}</div><div class="settings-row"><div><strong>Блокировка приложения</strong><small>${secure?'Системный PIN / пароль при каждом возврате':'Настройте блокировку экрана Android для защиты входа'}</small></div><button class="btn small" data-action="lock">${icon('lock')}</button></div><div class="section-divider"></div><div class="hero-bottom">${actButton('backup','Резервная копия','download','small')}${actButton('restore','Восстановить','upload','small')}</div><div class="hero-bottom">${actButton('demo','Демо-режим','spark','small ghost')}${actButton('privacy','Конфиденциальность','shield','small ghost')}</div><div class="notice">При удалении приложения его данные удаляются. Сохраните зашифрованную копию заранее. Пароль копии восстановить нельзя.</div><div class="source"><span>ASDTrecker · 1.1.0 · Android 8+</span><span>Сделано для вашего ритма</span></div>`);}
function backupModal(restore=false){if(demo){toast('Выйдите из демо-режима для работы с копиями');return;}modal(restore?'Восстановить данные':'Зашифрованная копия',`<form id="${restore?'restore':'backup'}-form">${restore?`<div class="field"><label for="backup-file">Файл .asdt</label>${native?'<button type="button" class="btn wide" data-action="pick-backup">Выбрать файл</button><small id="picked-file">Файл не выбран</small>':'<input id="backup-file" type="file" accept=".asdt,application/json" required>'}</div>`:''}<div class="field"><label for="backup-password">Пароль копии · минимум 12 символов</label><input id="backup-password" name="password" type="password" minlength="12" maxlength="256" required autocomplete="${restore?'current-password':'new-password'}"></div>${!restore?'<div class="field"><label for="backup-confirm">Повторите пароль</label><input id="backup-confirm" name="confirm" type="password" minlength="12" required autocomplete="new-password"></div>':''}<div class="notice">${restore?'Восстановление заменит все текущие записи, счета, бюджеты и цели.':'Копия защищена AES-256-GCM. Сохраните пароль отдельно: без него восстановление невозможно.'}</div>${restore?'<label class="settings-row"><input type="checkbox" name="consent" required>Подтверждаю замену текущих данных</label>':''}<div class="form-error" role="alert"></div><div class="modal-actions"><button class="btn primary" type="submit">${restore?'Восстановить':'Создать копию'}</button></div></form>`);pickedBackup=null;}
let pickedBackup=null;
window.onBackupPicked=text=>{pickedBackup=text;if($('#picked-file'))$('#picked-file').textContent='Файл выбран';};
window.onNativeMessage=msg=>toast(msg);
window.onAndroidBack=()=>{if(closeModal())return;if(page!=='overview'){page='overview';render();window.scrollTo(0,0);}else native?.exitApp();};
async function refreshRates(manual=false){if(demo){toast('В демо используются вымышленные курсы');return;}if(refreshing)return;if(!manual&&Date.now()-state.fetchedAt<300000)return;refreshing=true;try{let data;try{data=await fetchFx();}catch{}if(!data&&native){data=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{window.onNativeRates=()=>{};reject(Error('Курсы сейчас недоступны'));},22000);window.onNativeRates=text=>{clearTimeout(timer);try{resolve(JSON.parse(text));}catch(e){reject(e);}};native.fetchRates();});}else if(!data){const r=await fetch('https://open.er-api.com/v6/latest/USD',{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error();data=await r.json();}if(data.result!=='success'||data.base_code!=='USD'||!data.rates||data.rates.USD!==1||!Number.isFinite(data.time_last_update_unix))throw Error();if(commit(s=>{const nextAt=data.time_last_update_unix*1000;if(data.previousRates){s.previousRates=data.previousRates;s.previousRatesAt=data.previousAt*1000;}else if(s.ratesAt&&nextAt>s.ratesAt){s.previousRates=s.rates;s.previousRatesAt=s.ratesAt;}s.rates=data.rates;s.ratesAt=nextAt;s.fetchedAt=Date.now();if(data.central)s.fx={central:data.central,frequency:'daily'};})){render();if(manual)toast('Курсы обновлены. Старые операции сохранили свой курс.');}}catch{if(manual)toast('Не удалось обновить курсы. Сохранённые курсы остаются доступны.');}finally{refreshing=false;if($('#modal-title')?.textContent==='Ваше пространство')settings();}}
function confirmDelete(kind,id){const titles={transaction:'операцию',budget:'бюджет',goal:'цель',account:'счёт'};modal('Удалить '+titles[kind]+'?',`<p class="privacy-copy">${kind==='transaction'?'Запись будет удалена, учётный баланс и статистика пересчитаны.':'Действие нельзя отменить.'}</p><div class="modal-actions">${actButton('close','Отмена','close','ghost')}${actButton('delete-confirm','Удалить','trash','danger',`data-id="${id}" data-kind="${kind}"`)}</div>`);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
 switch(a){case'nav':page=id;render();window.scrollTo({top:0,behavior:'instant'});break;case'close':closeModal();break;case'add-expense':transactionModal('expense');break;case'add-income':transactionModal('income');break;case'period':period=id;render();break;case'hide':if(commit(s=>s.hidden=!s.hidden))render();break;case'detail':detail(id);break;case'transaction-edit':transactionModal('expense',id);break;case'select-category':selectedCategory=id;$('#category-buttons').innerHTML=categoryButtons();break;case'category-history':historyCategory=id;historyType='expense';page='history';render();window.scrollTo(0,0);break;case'budget-add':budgetModal();break;case'budget-edit':budgetModal(id);break;case'goal-add':goalModal();break;case'goal-edit':goalModal(id);break;case'account-add':accountModal();break;case'account-edit':accountModal(id);break;case'goal-save':{const g=state.goals.find(x=>x.id===id);modal('Записать накопления',`<form id="goal-save-form" data-id="${id}"><p class="privacy-copy">${esc(g.name)} · ${g.currency}</p><div class="field section-space"><label for="goal-add-amount">Сколько дополнительно отложили?</label><input id="goal-add-amount" name="amount" inputmode="decimal" required></div><small>Изменится только прогресс цели, баланс счёта останется прежним.</small><div class="form-error" role="alert"></div><div class="modal-actions"><button class="btn primary" type="submit">Записать</button></div></form>`);break;}case'currency':currencyModal();break;case'set-currency':if(commit(s=>s.currency=id)){closeModal();render();toast('Валюта сводки: '+id);}break;case'settings':settings();break;case'motion':if(commit(s=>s.motion=!s.motion)){render();settings();}break;case'refresh':refreshRates(true);break;case'lock':if(native){closeModal();native.lock();}else toast('Системная блокировка доступна в Android APK');break;case'demo':if(!demo){realState=state;state=demoState();demo=true;}closeModal();page='overview';render();window.scrollTo(0,0);break;case'exit-demo':state=realState;demo=false;closeModal();render();refreshRates();break;case'backup':backupModal();break;case'restore':backupModal(true);break;case'pick-backup':native?.pickBackup();break;case'privacy':modal('Ваши данные принадлежат вам',`<div class="privacy-copy"><p>Записи, счета, бюджеты и цели хранятся локально. Android-версия шифрует их AES-256-GCM, ключ хранится в Android Keystore. При настроенной блокировке телефона вход защищён системным PIN или паролем. При возврате из фона приложение блокируется.</p><p>Скриншоты и изображение приложения в списке недавних приложений закрыты. Облачное резервирование Android отключено. Копии создаются только вами и защищены отдельным паролем.</p><p>Без входа записи остаются локальными. После входа данные аккаунта автоматически синхронизируются с сервером ASDTrecker на Vercel и базой Neon по HTTPS. Финансовое содержимое в базе зашифровано отдельным серверным ключом. Это не сквозное шифрование: сервер приложения может расшифровать записи. Пароли хешируются Better Auth, сессии отделены от финансовых данных. Публичные курсы поступают от ExchangeRate-API и ЦБ Узбекистана; ваши записи этим источникам не передаются. Курсы справочные и обновляются источниками ежедневно.</p><p>Автоматического подключения банков нет. Приложение не запрашивает реквизиты карт, SMS, контакты, местоположение или доступ к уведомлениям. Платежей и переводов нет.</p><p>Веб-версия хранит локальную копию в localStorage браузера; Android использует Keystore. Выход удаляет локальную копию аккаунта, а облачная копия остаётся в Neon. На общем компьютере выходите из аккаунта. Восстановление пароля по email пока не подключено.</p></div>`);break;case'transaction-delete':case'budget-delete':case'goal-delete':case'account-delete':confirmDelete(a.split('-')[0],id);break;case'delete-confirm':{const key={transaction:'transactions',budget:'budgets',goal:'goals',account:'accounts'}[b.dataset.kind];if(key==='accounts'&&(state.accounts.length===1||state.transactions.some(t=>t.account===id))){toast('Счёт используется в операциях');return;}if(commit(s=>s[key]=s[key].filter(x=>x.id!==id))){closeModal();render();toast('Удалено');}break;}}
});
document.addEventListener('input',e=>{if(e.target.id==='currency-search')$('#currency-list').innerHTML=currencyRows(e.target.value);if(e.target.id==='history-search'){const start=e.target.selectionStart;query=e.target.value;render();$('#history-search').focus();$('#history-search').setSelectionRange(start,start);}});
document.addEventListener('change',e=>{if(e.target.id==='history-type'){historyType=e.target.value;render();}if(e.target.id==='history-category'){historyCategory=e.target.value;render();}if(e.target.id==='tx-currency'&&$('#tx-rate'))$('#tx-rate').value='';});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,f=new FormData(form),v=k=>String(f.get(k)||'').trim(),error=form.querySelector('.form-error');if(error)error.textContent='';try{let ok=false;
 if(form.id==='transaction-form'){const currency=v('currency'),amount=toMinor(v('amount'),currency),account=state.accounts.find(a=>a.id===v('account')),note=v('note'),date=v('date');if(!note)throw Error('Поясните, на что именно потратили или откуда получили деньги');if(!date||date>today()||date<'1900-01-01')throw Error('Выберите корректную дату не позднее сегодняшней');const rawRate=v('rate').replace(',','.');let rate=currency==='USD'?1:rawRate?Number(rawRate):state.rates[currency];if(rawRate&&(!Number.isFinite(rate)||rate<=0||rate>1e9))throw Error('Введите положительный курс');const value=fromMinor(amount,currency),usdValue=rate?value/rate:null;let accountAmount=amount;if(account.currency!==currency){if(usdValue===null||!state.rates[account.currency])throw Error('Для разных валют операции и счёта нужны курсы. Обновите курсы или выберите счёт в валюте операции.');accountAmount=Math.round(usdValue*state.rates[account.currency]*10**decimals(account.currency));}const old=state.transactions.find(t=>t.id===editing);if(old&&old.amount===amount&&old.currency===currency&&old.account===account.id&&old.usdValue!==null&&Math.abs(old.usdValue-(usdValue??0))<1e-8)accountAmount=old.accountAmount;const t={id:editing||uid(),type:txType,amount,currency,account:account.id,accountAmount,category:selectedCategory,note,date,usdValue};ok=commit(s=>{const i=s.transactions.findIndex(x=>x.id===editing);if(i>=0)s.transactions[i]=t;else s.transactions.push(t);});}
 else if(form.id==='budget-form'){const currency=v('currency'),category=v('category'),id=form.dataset.id;if(state.budgets.some(b=>b.category===category&&b.id!==id))throw Error('Для этой категории уже есть бюджет');const b={id:id||uid(),category,currency,limit:toMinor(v('limit'),currency)};ok=commit(s=>{s.budgets=s.budgets.filter(x=>x.id!==id);s.budgets.push(b);});}
 else if(form.id==='goal-form'){const id=form.dataset.id,currency=v('currency'),g={id:id||uid(),name:v('name'),currency,target:toMinor(v('target'),currency),saved:Number(v('saved').replace(',','.'))===0?0:toMinor(v('saved'),currency)};ok=commit(s=>{s.goals=s.goals.filter(x=>x.id!==id);s.goals.push(g);});}
 else if(form.id==='goal-save-form'){const g=state.goals.find(x=>x.id===form.dataset.id),amount=toMinor(v('amount'),g.currency);ok=commit(s=>s.goals.find(x=>x.id===g.id).saved+=amount);}
 else if(form.id==='account-form'){const id=form.dataset.id,existing=state.accounts.find(x=>x.id===id),used=state.transactions.some(t=>t.account===id),currency=used?existing.currency:v('currency'),raw=v('opening').replace(',','.'),opening=Number(raw)===0?0:toMinor(raw.replace(/^-/,' '),currency)*(raw.startsWith('-')?-1:1),a={id:id||uid(),name:v('name'),bank:v('bank'),currency,opening};ok=commit(s=>{const i=s.accounts.findIndex(x=>x.id===id);if(i>=0)s.accounts[i]=a;else s.accounts.push(a);});}
 else if(form.id==='backup-form'){if(v('password')!==v('confirm'))throw Error('Пароли не совпадают');const submit=form.querySelector('[type=submit]');submit.disabled=true;submit.textContent='Шифрование…';try{const text=await seal(state,v('password'));if(native)native.exportBackup(text);else{const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`ASDTrecker-${today()}.asdt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}closeModal();toast('Копия зашифрована. Сохраните файл в надёжном месте.');}finally{submit.disabled=false;submit.textContent='Создать копию';}return;}
 else if(form.id==='restore-form'){const submit=form.querySelector('[type=submit]');submit.disabled=true;submit.textContent='Проверка копии…';try{let text=pickedBackup;if(!native){const file=$('#backup-file').files[0];if(!file)throw Error('Выберите файл');if(file.size>15000000)throw Error('Файл слишком большой');text=await file.text();}if(!text)throw Error('Выберите файл');const recovered=validateState(await unseal(text,v('password')));const oldFailure=loadFailure;loadFailure=false;ok=commit(s=>{for(const k of Object.keys(s))delete s[k];Object.assign(s,recovered);});if(!ok)loadFailure=oldFailure;}finally{submit.disabled=false;submit.textContent='Восстановить';}}
 if(ok){closeModal();render();toast(demo?'Записано в демо. Ваши данные не изменены.':'Сохранено');}
 }catch(err){if(error)error.textContent=err.message;else toast(err.message);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('.modal')){const nodes=[...$('.modal').querySelectorAll('button,input,select,textarea,summary,a[href]')].filter(x=>!x.disabled&&x.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('online',()=>{render();refreshRates();});window.addEventListener('offline',render);
render();setupAccountUI({cloud,modal,closeModal,toast,isDemo:()=>demo,getState:()=>state,replaceState:s=>{loadFailure=false;realState=s;if(!demo)state=s;render();},request:cloudRequest,backup:()=>backupModal()});
setupFxUI({getState:()=>state,commit,modal,toast,isDemo:()=>demo,refresh:refreshRates});
if(!loadFailure){cloud.init().finally(()=>refreshRates());}
